#!/bin/zsh


<<comment

Run the following to download and log output

./8088_friendly.sh | tee 8088_friendly.log

View log with:

less 8088_friendly.log

comment


put_section_header () {
  local title="$1"
  local url="$2"

  echo "\n\n${title}"
  echo '------------------------------------------------------------'
  echo "target:\t$(pwd)"
  echo "source:\t${url}"
  echo
}


