base_target_dir="8088_friendly"
base_url="http://ftp.oldskool.org/pub/misc/Software/Games/8088-friendly"

for year in {1981..1988}; do 
  local source_url="${base_url}/${year}"
  local target_dir="${base_target_dir}/${year}/"
  mkdir -p "$target_dir"
  cd "$target_dir"  
  put_section_header "${base_target_dir} - ${year}" "$source_url"
  eval "fetch_${year} \"${source_url}\" \"${target_dir}\""
  cd -
done


